from strands import Agent, tool
from strands.models import BedrockModel

cheap_model = BedrockModel(model_id="us.anthropic.claude-haiku-4-5-20251001-v1:0")

billing_agent = Agent(
    model=cheap_model,
    system_prompt="You answer billing and invoice questions only.",
)
technical_agent = Agent(
    model=cheap_model,
    system_prompt="You answer technical/product usage questions only.",
)

@tool
def billing_specialist(query: str) -> str:
    """Answer a billing or invoice related question."""
    return str(billing_agent(query))

@tool
def technical_specialist(query: str) -> str:
    """Answer a technical or product usage question."""
    return str(technical_agent(query))

orchestrator = Agent(
    model=BedrockModel(model_id="us.anthropic.claude-sonnet-5"),
    tools=[billing_specialist, technical_specialist],
)

result = orchestrator("Why was I charged twice this month?")
